<?php ob_start(); ?><?php $__blade->comecar('conteudo'); ?><h1>Posts (<?php echo e($posts->total()); ?>)</h1><?php foreach ($posts as $p): ?><a href="<?php echo e(route('posts.show', $p)); ?>"><?php echo e($p->titulo); ?></a> (<?php echo e($p->comentarios->count()); ?>)<?php endforeach; ?><?php echo e($posts->links()); ?><?php if ($errors->any()): ?><p class="erro"><?php echo e($errors->first('titulo')); ?></p><?php endif; ?><form method="POST" action="<?php echo e(route('posts.store')); ?>"><input name="titulo" value="<?php echo e(old('titulo')); ?>"></form><?php $__blade->terminar(); ?><?php ob_end_clean(); echo $__blade->incluir('layouts.app', get_defined_vars()); ?>
